<script setup lang="ts">
import { formatDemoTime } from '~/domain/selectors'

definePageMeta({ layout: 'workspace' })
useHead({ title: 'Bukti pengiriman · UKIN PPG UNJ' })
const ukin = useUkin()
const route = useRoute()
const result = computed(() => {
  void ukin.snapshot.value
  void ukin.user.value
  try {
    const id = typeof route.query.id === 'string' ? route.query.id : ''
    if (!id) throw new Error('Pilih bukti pengiriman dari halaman paket atau daftar pemeriksaan.')
    return { view: ukin.getEvidence(id), error: '' }
  } catch (cause) { return { view: null, error: cause instanceof Error ? cause.message : 'Bukti belum dapat dibuka.' } }
})
const view = computed(() => result.value.view)
const latestReview = computed(() => view.value?.reviews.at(-1))
const versionHistory = computed(() => (view.value?.history ?? []).filter(item => item.evidenceVersionId === view.value?.version.id))
const componentLabels = { perangkat: 'Perangkat pembelajaran', video: 'Video praktik', studi_kasus: 'Studi kasus' }
const actionLabels: Record<string, string> = {
  submitted: 'Paket dikirim', resubmitted: 'Paket dikirim ulang', package_submitted: 'Paket dikirim', package_resubmitted: 'Paket dikirim ulang',
  complete: 'Pemeriksaan lengkap', marked_complete: 'Pemeriksaan lengkap', completeness_complete: 'Pemeriksaan lengkap',
  correction_requested: 'Perbaikan teknis diminta', revision_requested: 'Perbaikan teknis diminta', needs_correction: 'Perbaikan teknis diminta',
  file_restored: 'File lokal dipulihkan', restore_file: 'File lokal dipulihkan',
}
function actionLabel(action: string) { return actionLabels[action] ?? action }
</script>

<template>
  <div v-if="view" class="receipt-page">
    <NuxtLink v-if="ukin.user.value?.role === 'peserta'" :to="`/app/paket?id=${view.attempt.id}`" class="text-link back-link"><AppIcon name="arrow-left" :size="17" />Kembali ke paket</NuxtLink>
    <NuxtLink v-else :to="ukin.home.value" class="text-link back-link"><AppIcon name="arrow-left" :size="17" />Kembali ke ringkasan</NuxtLink>
    <header class="receipt-hero"><div class="receipt-emblem"><AppIcon name="check" :size="30" /></div><div><p class="eyebrow">BUKTI PENGIRIMAN UKIN</p><h1>Paket versi {{ view.version.version }} tersimpan<span>.</span></h1><p>Snapshot bukti pengiriman ini dikunci. Kelengkapan administratif diperiksa secara terpisah.</p></div><span class="receipt-version">V{{ view.version.version }}</span></header>
    <section class="panel receipt-details" aria-label="Identitas bukti pengiriman"><div class="receipt-number"><p>Nomor bukti pengiriman</p><strong>{{ view.version.receipt }}</strong><span>{{ formatDemoTime(view.version.submittedAt) }} · Waktu demo</span></div><dl><div><dt>Peserta</dt><dd>{{ view.participant.displayName }}</dd></div><div><dt>Bidang studi</dt><dd>{{ view.attempt.subject }}</dd></div><div><dt>Periode</dt><dd>{{ view.period.name }}</dd></div><div><dt>Percobaan</dt><dd>{{ view.attempt.attemptNumber }}{{ view.attempt.previousAttemptId ? ' · Retaker, riwayat lama tetap terpisah' : '' }}</dd></div></dl></section>
    <p v-if="view.version.fixture" class="notice">Bukti ini adalah contoh bawaan yang dibuat untuk simulasi. Tidak berasal dari pengiriman peserta nyata.</p>
    <p v-if="!view.isCurrent" class="notice archive-notice"><strong>Arsip versi sebelumnya.</strong> Ada versi paket yang lebih baru. Bukti pada halaman ini tetap disimpan untuk riwayat dan tidak diganti oleh isi versi baru.</p>
    <section class="panel review-summary" aria-labelledby="review-summary-title"><div class="review-heading"><div><p class="eyebrow">PEMERIKSAAN KELENGKAPAN</p><h2 id="review-summary-title">{{ latestReview?.outcome === 'complete' ? 'Lengkap secara administratif' : latestReview?.outcome === 'needs_correction' ? 'Perbaikan teknis diperlukan' : 'Menunggu pemeriksaan pengelola' }}</h2></div><AppIcon :name="latestReview?.outcome === 'complete' ? 'check' : 'clock'" :size="26" /></div><p>Kelengkapan bukan keputusan kompetensi, kelulusan, atau nilai. Kendala dokumen dan video tidak otomatis menjadi skor nol.</p><template v-if="latestReview"><div class="review-meta">{{ latestReview.actorName }} · {{ formatDemoTime(latestReview.reviewedAt) }} <span v-if="latestReview.fixture">· Pemeriksaan simulasi bawaan</span></div><ul v-if="latestReview.outcome === 'needs_correction'" class="review-issues"><li v-for="(reason, component) in latestReview.issues" :key="component"><strong>{{ componentLabels[component] }}</strong><p>{{ reason }}</p></li></ul></template><UButton v-if="ukin.user.value?.role === 'peserta' && view.isCurrent && view.attempt.packageStatus === 'revision_requested'" :to="`/app/paket?id=${view.attempt.id}`" class="revision-link">Buka draf perbaikan <AppIcon name="arrow-right" :size="17" /></UButton></section>
    <div class="evidence-heading"><div><p class="eyebrow">SNAPSHOT PAKET V{{ view.version.version }}</p><h2>Tiga komponen bukti</h2></div><span class="status-badge"><AppIcon name="shield" :size="15" />Terkunci</span></div>
    <AttemptHistory :attempts="view.attemptHistory" :current-attempt-id="view.attempt.id" />
    <EvidenceReadView :content="view.version.content" :can-restore="view.canRestore" :version-id="view.version.id" />
    <p class="notice persistence-note">Bukti tersimpan pada browser dan origin ini. File bawaan tetap dapat dibuka setelah refresh. File lokal memerlukan pemilihan ulang dengan isi yang cocok; isi video YouTube tetap berada di platform eksternal.</p>
    <section class="panel history-panel" aria-labelledby="history-title"><div class="section-heading"><h2 id="history-title">Jejak tindakan versi ini</h2><span class="muted">Waktu demo · Data lokal</span></div><ol v-if="versionHistory.length" class="history-list"><li v-for="event in versionHistory" :key="event.id"><span class="history-dot" /><div><h3>{{ actionLabel(event.action) }} <span v-if="event.fixture">Simulasi bawaan</span></h3><p>{{ event.actorName }} · {{ formatDemoTime(event.at) }}</p><p v-if="event.reason" class="history-reason">{{ event.reason }}</p></div></li></ol><p v-else class="muted">Pengiriman dicatat pada identitas bukti di atas. Belum ada tindakan pemeriksaan lain pada versi ini.</p></section>
  </div>
  <section v-else class="panel unavailable"><AppIcon name="file" :size="36" /><h1>Bukti pengiriman tidak tersedia.</h1><p>{{ result.error }}</p><UButton :to="ukin.home.value">Kembali ke ringkasan</UButton></section>
</template>

