@media(max-width:600px){.receipt-hero{align-items:flex-start;padding:24px;gap:15px}.receipt-emblem{height:40px;width:40px;border-radius:12px}.receipt-emblem svg{width:24px}.receipt-hero h1{font-size:26px}.receipt-hero .eyebrow{font-size:9px}.receipt-details dl>div{grid-template-columns:80px 1fr;font-size:12px;gap:10px}.receipt-number strong{font-size:17px}.review-summary h2{font-size:21px}.evidence-heading h2{font-size:21px}.evidence-heading .status-badge{font-size:11px}.history-panel .section-heading{align-items:flex-start;flex-direction:column;gap:8px}.history-list h3 span{display:block;width:fit-content;margin:5px 0}}
